root=Path(__file__).resolve().parent;src=root.parent;runtime=Path('/opt/openg2p-lab');app=runtime/'registration';now=datetime.datetime.now(datetime.timezone.utc).isoformat();stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S');backup=runtime/'knowledge-corrections'/('restored-screens-'+stamp);backup.mkdir(mode=0o700)
definitions=[
 ('partner-management','Partner requests',r'/requests(?:/|$)','Review a partner onboarding or change request before recording its outcome.','Open the request and confirm the partner and requested change.\nReview the supplied information and any previous decision or processing status.\nUse only the decision or correction control available to your role, then confirm the new request status.'),
 ('partner-management','Partner onboarding',r'/onboard(?:/|$)','Prepare a partner onboarding request with the required organisation and integration information.','Check the partner list for an existing organisation.\nComplete the onboarding fields and review contact information, requested scope and any key material.\nSubmit only an authorised request and follow its status in Requests.'),
 ('master-data-ui','Geographic levels',None,'Manage the hierarchy levels used to organise geographic reference values.','Review the existing levels and their order before editing.\nCheck how country, state and local-area values depend on the proposed level.\nSave only an agreed change and confirm the resulting hierarchy. Do not remove a level that is still required by existing values.'),
 ('iam-staff-ui','Application configuration',r'/applications(?:/|$)','Maintain the applications and permitted destinations available through the staff service.','Open an existing application or the Add form.\nCheck the application identifier, display name, destination and enabled state.\nSave only an authorised change and verify that the application opens at its intended address.'),
 ('iam-staff-ui','Login provider configuration',r'/login-providers(?:/|$)','Review the identity-provider settings used by staff sign-in.','Open the intended login provider and review its issuer, client and callback settings.\nConfirm the proposed settings with the identity administrator; do not copy secrets into help or support messages.\nSave only an authorised change and verify a complete sign-in and return to the requested service.'),
 ('odk','Field collection users',r'^/users(?:/|$)','Review the user accounts available to the field collection service.','Locate the existing user before adding a duplicate account.\nCheck account status and project responsibilities.\nUse permitted account controls only for an authorised change, then confirm the resulting access.'),
 ('odk','Collection system audit',r'^/system/audits(?:/|$)','Inspect recorded field-collection administration events.','Select the relevant time period or event filters.\nRead the actor, action and timestamp for the event under investigation.\nUse the event reference and current project state together when reporting a discrepancy.'),
 ('odk','Usage reporting',r'^/system/analytics(?:/|$)','Review the field collection service’s usage-reporting settings and information.','Read the description of the information collected and where it is sent.\nCheck the current reporting setting.\nChange the setting only when authorised by the service owner and verify that the saved choice is shown.'),
 ('odk','Collection account profile',r'^/account/edit(?:/|$)','Review the profile of the currently signed-in collection user.','Confirm that the account is your own.\nCheck the profile values and permitted edit fields.\nSave supported corrections and verify the updated profile. Use the identity-provider process for credentials managed by single sign-on.'),
 ('superset','Analytics datasets',r'^/(?:tablemodelview|dataset)(?:/|$)','Review the datasets that supply analytics charts and dashboards.','Find the dataset used by the intended report.\nCheck its source, columns and calculated measures before editing.\nMake only authorised changes and verify the affected chart with its existing filters.'),
 ('beneficiary','Portal information',r'/(?:aboutus|contactus|otherpage)(?:/|$)','Read the portal’s service information and contact instructions.','Open the relevant information page and read the full guidance.\nUse the listed service contact or enquiry route for questions about your application.\nInclude only the reference and information requested; never send passwords or unnecessary account details.'),
]
db=sqlite3.connect(app/'intake.sqlite');db.row_factory=sqlite3.Row
with sqlite3.connect(backup/'intake.sqlite') as copy:db.backup(copy)
guides=[];routes=[]
with db:
 for mod,stage,pattern,purpose,steps in definitions:
  if pattern:routes.append(dict(module=mod,stage=stage,pattern=pattern))
  # Reuse an already published task when the exact context exists.
  if db.execute('SELECT 1 FROM km_articles WHERE module=? AND stage=? AND audience=?',(mod,stage,'all')).fetchone():continue
  a=dict(module=mod,stage=stage,audience='all',title=stage,purpose=purpose,steps=steps,requirements='An account authorised for this screen and the correct record, application or project reference.',next_step='Confirm the saved values or displayed status before continuing with the related task.',issues='Check active filters and resolve the displayed validation message before retrying. If a control is unavailable, ask the service administrator to verify your permissions. Do not use a configuration change to bypass an approval or access requirement.',scope='local_workflow',visibility='public')
  slug='nsipa-restored-'+mod+'-'+re.sub('[^a-z0-9]+','-',stage.lower());content=json.dumps(a);actor='system:nsipa-restored-screen-help';note='User-requested guidance for restored authenticated screens; maintenance publication.'
  cur=db.execute("INSERT INTO km_articles(slug,module,stage,audience,draft,version,status,author,published,published_version,updated,review_note) VALUES(?,?,?,?,?,1,'published',?,?,1,?,?)",(slug,mod,stage,'all',content,actor,content,now,note))
  db.execute('INSERT INTO km_history(article,version,action,actor,at,content,note) VALUES(?,1,?,?,?,?,?)',(cur.lastrowid,'maintenance_publication',actor,now,content,note));guides.append(dict(slug=slug,**a))
for p in [src/'knowledge-seed.json',root/'seed.json',app/'knowledge-seed.json']:
 data=json.loads(p.read_text());data['articles']+=guides;p.write_text(json.dumps(data,ensure_ascii=False,indent=2))
p=root/'context.js';s=p.read_text();match=re.search(r' const screenRoutes=(.*);\n',s);existing=json.loads(match.group(1));newroutes=routes+existing;s=s[:match.start(1)]+json.dumps(newroutes,separators=(',',':'))+s[match.end(1):]
