s=s.replace("stage=mod==='registry'?'Household membership':'Enrollment'","stage=mod==='registry'?'Household membership':mod==='portal-admin'?'Application administration':'Enrollment'")
s=s.replace("if(/\\/applications/.test(path))stage='Application status';","if(/\\/home(?:\\/|$)/.test(path))return use('beneficiary','Beneficiary dashboard','screen route');\n   if(/\\/applications/.test(path))stage='Application status';")
shutil.copy2('/opt/openg2p-lab/branding/knowledge-context.js',backup/'knowledge-context.js');p.write_text(s);shutil.copy2(p,'/opt/openg2p-lab/branding/knowledge-context.js')
p=root/'help.js';s=p.read_text().replace("explicit:area?.dataset.kmModule","dialog:!!modal,explicit:area?.dataset.kmModule");shutil.copy2('/opt/openg2p-lab/branding/knowledge-help.js',backup/'knowledge-help.js');p.write_text(s);shutil.copy2(p,'/opt/openg2p-lab/branding/knowledge-help.js')
